-- Permission gate example: block dangerous bash tool calls and explain via v4 UI.
local dangerous_patterns = { "rm%s+%-r", "rm%s+%-f", "rm%s+%-%-recursive", "%f[%w]sudo%f[%W]", "chmod%s+.-777", "chown%s+.-777" }
local function lower(s) return string.lower(tostring(s or "")) end
local function is_bash_tool(name) name = lower(name); return name == "bash" end
local function is_dangerous(command) local c = lower(command); for _, pattern in ipairs(dangerous_patterns) do if string.find(c, pattern) then return true end end; return false end
local function notice(ctx, command) if ctx and ctx.ui and ctx.ui.view.set then ctx.ui.view.set({ id = "permission-gate", slot = { kind = "overlay", width = "70%", anchor = "center", backdrop = "dim" }, keys = { { key = "escape", action = "close" }, { key = "q", action = "close" } }, root = { type = "view", style = { chrome = { kind = "frame", title = "Dangerous command blocked", border = "rounded", tone = "muted" }, padding = 1 }, children = { { type = "text", text = "Blocked dangerous bash command." }, { type = "text", text = command } } } }) end end
zi.define.event("ui", function(ctx, event) if event.view == "permission-gate" and ctx and ctx.ui and ctx.ui.view.set then ctx.ui.view.set({ id = "permission-gate", remove = true }) end end)
zi.define.event("tool_call", function(ctx, event) if not is_bash_tool(event.toolName) then return nil end; local input = event.input or {}; local command = tostring(input.command or input.cmd or ""); if not is_dangerous(command) then return nil end; notice(ctx, command); return { block = true, reason = "Dangerous bash command blocked by permission_gate example" } end)
